def add_to_watchlist(stock, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0218000" if __import__("os").path.isdir("./environment_mix/0218000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    state = _load("state.json")
    # state.json is modeled as a single object; tolerate empty/malformed storage.
    if not isinstance(state, dict):
        state = {}

    # Ensure audit log exists in state (service has no explicit audit collection).
    audit = state.get("request_log")
    if not isinstance(audit, list):
        audit = []
        state["request_log"] = audit

    def _log(status, code=None, message=None):
        dt = datetime.datetime.utcnow()
        latency_ms = int((dt - t0).total_seconds() * 1000)
        entry = {
            "ts": dt.isoformat() + "Z",
            "endpoint": "add_to_watchlist",
            "status": status,
            "latency_ms": latency_ms
        }
        if code or message:
            entry["error"] = {"code": code, "message": message}
        audit.append(entry)
        state["request_count"] = int(state.get("request_count") or 0) + 1
        _save("state.json", state)

    # Validate
    if not isinstance(stock, str):
        _log("error", "VALIDATION_ERROR", "stock must be a string.")
        return _err("VALIDATION_ERROR", "stock must be a string.")
    sym = stock.strip().upper()
    if not sym:
        _log("error", "VALIDATION_ERROR", "stock is required.")
        return _err("VALIDATION_ERROR", "stock is required.")

    if not state.get("authenticated", False):
        _log("error", "UNAUTHORIZED", "No active session.")
        return _err("UNAUTHORIZED", "No active session.")

    stocks = state.get("stocks")
    if not isinstance(stocks, dict) or not stocks:
        _log("error", "CONFLICT", "Market data is unavailable for this session.")
        return _err("CONFLICT", "Market data is unavailable for this session.")

    if sym not in stocks:
        _log("error", "NOT_FOUND", f"Unknown symbol: {sym}.")
        return _err("NOT_FOUND", f"Unknown symbol: {sym}.")

    wl = state.get("watch_list")
    if wl is None:
        wl = []
        state["watch_list"] = wl
    if not isinstance(wl, list):
        _log("error", "CONFLICT", "Watchlist storage is corrupted.")
        return _err("CONFLICT", "Watchlist storage is corrupted.")

    wl_norm = [str(x).strip().upper() for x in wl if isinstance(x, str)]
    if sym in wl_norm:
        _log("error", "CONFLICT", f"Symbol {sym} is already on the watchlist.")
        return _err("CONFLICT", f"Symbol {sym} is already on the watchlist.")

    # Mutate & persist
    wl.append(sym)
    state["watch_list"] = wl
    _log("ok")
    return {"symbol": sym, "watch_list": wl}

def cancel_order(order_id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0218000" if __import__("os").path.isdir("./environment_mix/0218000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    state = _load("state.json")
    if not isinstance(state, dict):
        state = {}

    audit = state.get("request_log")
    if not isinstance(audit, list):
        audit = []
        state["request_log"] = audit

    def _log(status, code=None, message=None):
        dt = datetime.datetime.utcnow()
        latency_ms = int((dt - t0).total_seconds() * 1000)
        entry = {
            "ts": dt.isoformat() + "Z",
            "endpoint": "cancel_order",
            "status": status,
            "latency_ms": latency_ms
        }
        if code or message:
            entry["error"] = {"code": code, "message": message}
        audit.append(entry)
        state["request_count"] = int(state.get("request_count") or 0) + 1
        _save("state.json", state)

    if not isinstance(order_id, int):
        _log("error", "VALIDATION_ERROR", "order_id must be an integer.")
        return _err("VALIDATION_ERROR", "order_id must be an integer.")
    if order_id <= 0:
        _log("error", "VALIDATION_ERROR", "order_id must be positive.")
        return _err("VALIDATION_ERROR", "order_id must be positive.")

    if not state.get("authenticated", False):
        _log("error", "UNAUTHORIZED", "No active session.")
        return _err("UNAUTHORIZED", "No active session.")

    orders = state.get("orders")
    if orders is None:
        orders = []
        state["orders"] = orders

    if not isinstance(orders, list):
        _log("error", "CONFLICT", "Orders storage is corrupted.")
        return _err("CONFLICT", "Orders storage is corrupted.")

    idx = None
    for i, o in enumerate(orders):
        if isinstance(o, dict) and o.get("id") == order_id:
            idx = i
            break

    if idx is None:
        _log("error", "NOT_FOUND", f"Order {order_id} not found.")
        return _err("NOT_FOUND", f"Order {order_id} not found.")

    order = orders[idx]
    status = order.get("status")
    if status in ("Completed", "Cancelled"):
        _log("error", "INVALID_TRANSITION", f"Order {order_id} is not cancellable from status '{status}'.")
        return _err("INVALID_TRANSITION", f"Order {order_id} is not cancellable from status '{status}'.")

    if status not in ("Open", "Pending"):
        _log("error", "INVALID_TRANSITION", f"Order {order_id} is not cancellable from status '{status}'.")
        return _err("INVALID_TRANSITION", f"Order {order_id} is not cancellable from status '{status}'.")

    # Mutate & persist
    order["status"] = "Cancelled"
    order["cancelled_at"] = datetime.datetime.utcnow().isoformat() + "Z"
    orders[idx] = order
    state["orders"] = orders
    _log("ok")
    return {"order": order}

