def filter_stocks_by_price(stocks, min_price, max_price):
    import json, os, math, random
    _S = json.load(open(os.path.join(_DB, 'state.json'), encoding='utf-8'))
    try:
        min_price = float(min_price); max_price = float(max_price)
    except (TypeError, ValueError):
        return {"error": "min_price and max_price must be numbers."}
    if not isinstance(stocks, list):
        stocks = [stocks]
    sd = _S.get("stocks", {})
    filtered = [s for s in stocks
                if sd.get(s, {}).get("price", 0) >= min_price
                and sd.get(s, {}).get("price", 0) <= max_price]
    return {"filtered_stocks": filtered}

