def get_symbol_by_name(name, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0218000" if __import__("os").path.isdir("./environment_mix/0218000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    state = _load("state.json")
    if not isinstance(state, dict):
        state = {}

    audit = state.get("request_log")
    if not isinstance(audit, list):
        audit = []
        state["request_log"] = audit

    def _log(status, code=None, message=None):
        dt = datetime.datetime.utcnow()
        latency_ms = int((dt - t0).total_seconds() * 1000)
        entry = {
            "ts": dt.isoformat() + "Z",
            "endpoint": "get_symbol_by_name",
            "status": status,
            "latency_ms": latency_ms
        }
        if code or message:
            entry["error"] = {"code": code, "message": message}
        audit.append(entry)
        state["request_count"] = int(state.get("request_count") or 0) + 1
        _save("state.json", state)

    if not isinstance(name, str):
        _log("error", "VALIDATION_ERROR", "name must be a string.")
        return _err("VALIDATION_ERROR", "name must be a string.")
    q = name.strip()
    if not q:
        _log("error", "VALIDATION_ERROR", "name is required.")
        return _err("VALIDATION_ERROR", "name is required.")

    stocks = state.get("stocks")
    if not isinstance(stocks, dict) or not stocks:
        _log("error", "CONFLICT", "Market data is unavailable for symbol lookup.")
        return _err("CONFLICT", "Market data is unavailable for symbol lookup.")

    # Schema has no company-name mapping; infer by matching query against the symbol itself.
    q_up = q.upper()
    matches = sorted([sym for sym in stocks.keys() if isinstance(sym, str) and q_up in sym.upper()])

    # If no matches, return empty set (not an error) would violate description; it "refuses" missing matches.
    if not matches:
        _log("error", "NOT_FOUND", "No matching company/symbol found.")
        return _err("NOT_FOUND", "No matching company/symbol found.")

    # Refuse overly ambiguous queries when can't determine unique match
    if len(matches) > 10:
        _log("error", "CONFLICT", "Query is too ambiguous; please provide a more specific name.")
        return _err("CONFLICT", "Query is too ambiguous; please provide a more specific name.", matches_count=len(matches))

    _log("ok")
    return {"query": q, "symbols": matches, "total": len(matches)}

def get_transaction_history(start_date=None, end_date=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0218000" if __import__("os").path.isdir("./environment_mix/0218000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    state = _load("state.json")
    if not isinstance(state, dict):
        state = {}

    audit = state.get("request_log")
    if not isinstance(audit, list):
        audit = []
        state["request_log"] = audit

    def _log(status, code=None, message=None):
        dt = datetime.datetime.utcnow()
        latency_ms = int((dt - t0).total_seconds() * 1000)
        entry = {
            "ts": dt.isoformat() + "Z",
            "endpoint": "get_transaction_history",
            "status": status,
            "latency_ms": latency_ms
        }
        if code or message:
            entry["error"] = {"code": code, "message": message}
        audit.append(entry)
        state["request_count"] = int(state.get("request_count") or 0) + 1
        _save("state.json", state)

    if not state.get("authenticated", False):
        _log("error", "UNAUTHORIZED", "User not authenticated.")
        return _err("UNAUTHORIZED", "User not authenticated.")

    # Validate optional dates. Some callers may pass literal "None" (string) due to tool schema default.
    def _parse_ymd(v, label):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if s == "" or s.lower() == "none":
                return None
            try:
                return datetime.datetime.strptime(s, "%Y-%m-%d").date()
            except ValueError:
                return _err("VALIDATION_ERROR", f"{label} must be in YYYY-MM-DD format.")
        return _err("VALIDATION_ERROR", f"{label} must be a string in YYYY-MM-DD format.")

    sd = _parse_ymd(start_date, "start_date")
    if isinstance(sd, dict) and "error" in sd:
        _log("error", sd["error"]["code"], sd["error"]["message"])
        return sd
    ed = _parse_ymd(end_date, "end_date")
    if isinstance(ed, dict) and "error" in ed:
        _log("error", ed["error"]["code"], ed["error"]["message"])
        return ed

    if sd and ed and sd > ed:
        _log("error", "VALIDATION_ERROR", "start_date must be on or before end_date.")
        return _err("VALIDATION_ERROR", "start_date must be on or before end_date.")

    # Supported historical window: if data exists, bound by min/max year range in data.
    history = state.get("transaction_history")
    if history is None:
        history = []
        state["transaction_history"] = history
    if not isinstance(history, list):
        _log("error", "CONFLICT", "Transaction history storage is corrupted.")
        return _err("CONFLICT", "Transaction history storage is corrupted.")

    def _parse_tx_ts(ts):
        if not isinstance(ts, str):
            return None
        s = ts.strip()
        if not s:
            return None
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"):
            try:
                return datetime.datetime.strptime(s, fmt)
            except ValueError:
                continue
        return None

    out = []
    for tx in history:
        if not isinstance(tx, dict):
            continue
        ts = _parse_tx_ts(tx.get("timestamp"))
        if ts is None:
            continue
        tx_date = ts.date()
        if sd and tx_date < sd:
            continue
        if ed and tx_date > ed:
            continue
        out.append(tx)

    _log("ok")
    return {"transaction_history": out, "total": len(out)}

