    if acct.get("account_id") != account_id:
        _log("error", "NOT_FOUND", f"Account with ID {account_id} not found.")
        return _err("NOT_FOUND", f"Account with ID {account_id} not found.")

    bal = acct.get("balance")
    try:
        bal = float(bal)
    except Exception:
        _log("error", "CONFLICT", "Account balance is corrupted.")
        return _err("CONFLICT", "Account balance is corrupted.")

    xt = xact_type.strip().lower()
    if xt not in ("deposit", "withdrawal"):
        _log("error", "VALIDATION_ERROR", "Invalid transaction type. Use 'deposit' or 'withdrawal'.")
        return _err("VALIDATION_ERROR", "Invalid transaction type. Use 'deposit' or 'withdrawal'.")

    if xt == "withdrawal" and amt > bal:
        _log("error", "CONFLICT", "Insufficient funds.")
        return _err("CONFLICT", "Insufficient funds.")

    new_balance = bal + amt if xt == "deposit" else bal - amt

    # Mutate & persist: update balance and append transaction
    acct["balance"] = new_balance
    state["account_info"] = acct

    history = state.get("transaction_history")
    if history is None:
        history = []
        state["transaction_history"] = history
    if not isinstance(history, list):
        _log("error", "CONFLICT", "Transaction history storage is corrupted.")
        return _err("CONFLICT", "Transaction history storage is corrupted.")

    now = datetime.datetime.utcnow()
    tx = {
        "type": xt,
        "amount": amt,
        "timestamp": now.strftime("%Y-%m-%d %H:%M:%S")
    }
    history.append(tx)
    state["transaction_history"] = history
    _log("ok")
    return {"transaction": tx, "balance": new_balance, "account_id": account_id}

