        audit.append(entry)
        state["request_count"] = int(state.get("request_count") or 0) + 1
        _save("state.json", state)

    if not isinstance(stocks, list) or not stocks:
        _log("error", "VALIDATION_ERROR", "stocks must be a non-empty list of symbols.")
        return _err("VALIDATION_ERROR", "stocks must be a non-empty list of symbols.")
    if not isinstance(threshold, (int, float)):
        _log("error", "VALIDATION_ERROR", "threshold must be a number.")
        return _err("VALIDATION_ERROR", "threshold must be a number.")
    thr = float(threshold)
    if not (thr > 0):
        _log("error", "VALIDATION_ERROR", "threshold must be positive.")
        return _err("VALIDATION_ERROR", "threshold must be positive.")

    sd = state.get("stocks")
    if not isinstance(sd, dict) or not sd:
        _log("error", "CONFLICT", "Market data is unavailable.")
        return _err("CONFLICT", "Market data is unavailable.")

    unknown = []
    unpriced = []
    triggered = []
    checked = []

    for s in stocks:
        if not isinstance(s, str) or not s.strip():
            continue
        sym = s.strip().upper()
        checked.append(sym)
        if sym not in sd:
            unknown.append(sym)
            continue
        rec = sd.get(sym)
        if not isinstance(rec, dict):
            unpriced.append(sym)
            continue
        pc = rec.get("percent_change", None)
        if not isinstance(pc, (int, float)):
            unpriced.append(sym)
            continue
        if abs(float(pc)) >= thr:
            triggered.append({"symbol": sym, "percent_change": float(pc)})

    if unknown:
        _log("error", "NOT_FOUND", "Unknown symbols requested.")
        return _err("NOT_FOUND", "Unknown symbols requested.", unknown_symbols=sorted(set(unknown)))
    if unpriced:
        _log("error", "CONFLICT", "Market data unavailable for one or more requested symbols.")
        return _err("CONFLICT", "Market data unavailable for one or more requested symbols.", unavailable_symbols=sorted(set(unpriced)))

    _log("ok")
    return {
        "threshold": thr,
        "checked": checked,
        "triggered": triggered,
        "total_triggered": len(triggered)
    }

