        return _err("VALIDATION_ERROR", "price must be a number.")
    if not isinstance(amount, int):
        _log("error", "VALIDATION_ERROR", "amount must be an integer.")
        return _err("VALIDATION_ERROR", "amount must be an integer.")

    ot = order_type.strip()
    if ot not in ("Buy", "Sell"):
