    if ot == "Buy":
        total = px * float(amount)
        if total > bal:
            _log("error", "CONFLICT", "Insufficient buying power.")
            return _err("CONFLICT", "Insufficient buying power.", required=total, available=bal)

    # Create order
    try:
        oc = int(state.get("order_counter") or 0)
