def update_market_status(current_time_str, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0218000" if __import__("os").path.isdir("./environment_mix/0218000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if current_time_str is None or not isinstance(current_time_str, str) or not current_time_str.strip():
        return _err("VALIDATION_ERROR", "current_time_str is required and must be a non-empty string in HH:MM AM/PM format.")

    try:
        current = datetime.datetime.strptime(current_time_str.strip(), "%I:%M %p")
    except ValueError:
        return _err("VALIDATION_ERROR", "Invalid time format. Use HH:MM AM/PM.")

    # Market hours rules: 09:30 AM - 04:00 PM inclusive.
    market_open = datetime.datetime.strptime("09:30 AM", "%I:%M %p")
    market_close = datetime.datetime.strptime("04:00 PM", "%I:%M %p")

    new_status = "Open" if (market_open <= current <= market_close) else "Closed"

    state = _load("state.json")
    if not isinstance(state, dict) or not state:
        return _err("NOT_FOUND", "No session state found to update market status.")

    # Always require an authenticated session to update session market status (session-scoped rule).
    if state.get("authenticated") is not True:
        return _err("UNAUTHORIZED", "No active authenticated session for updating market status.")

    prior = state.get("market_status")
    state["market_status"] = new_status

    if prior == new_status:
        # Idempotent update is still a real write only if we persist it? Real services often avoid a write,
        # but we must also ensure observable state; if nothing changed, return existing state without saving.
        return {
            "market_status": state.get("market_status"),
            "current_time_str": current_time_str.strip(),
            "changed": False
        }

    try:
        _save("state.json", state)
    except Exception:
        return _err("CONFLICT", "Failed to persist updated market status.")

    return {
        "market_status": state.get("market_status"),
        "current_time_str": current_time_str.strip(),
        "changed": True
    }

def update_stock_price(symbol, new_price, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0218000" if __import__("os").path.isdir("./environment_mix/0218000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if symbol is None or not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string.")
    symbol = symbol.strip().upper()

    # Accept numeric strings as real APIs often do; reject non-numeric (e.g., "AAPL")
    if new_price is None:
        return _err("VALIDATION_ERROR", "new_price is required and must be a positive number.")
    try:
        price = float(new_price)
    except (TypeError, ValueError):
        return _err("VALIDATION_ERROR", "new_price must be a number.")

    if not (price > 0):
        return _err("VALIDATION_ERROR", "new_price must be greater than 0.")

    state = _load("state.json")
    if not isinstance(state, dict) or not state:
        return _err("NOT_FOUND", "No session state found to update stock price.")

    if state.get("authenticated") is not True:
        return _err("UNAUTHORIZED", "No active authenticated session for updating stock prices.")

    stocks = state.get("stocks")
    if not isinstance(stocks, dict) or not stocks:
        return _err("NOT_FOUND", "No market data available to update.")

    if symbol not in stocks or not isinstance(stocks.get(symbol), dict):
        return _err("NOT_FOUND", f"Stock with symbol '{symbol}' not found.")

    rec = stocks[symbol]
    old_price = rec.get("price")
    try:
        old_price_f = float(old_price) if old_price is not None else None
    except (TypeError, ValueError):
        old_price_f = None

    # Update percent_change relative to previous price when possible.
    if old_price_f and old_price_f != 0:
        pct = (price - old_price_f) / old_price_f * 100.0
    else:
        pct = 0.0

    rec["price"] = price
    rec["percent_change"] = float(round(pct, 2))
    # Volume/MA fields are left unchanged (not derivable from this endpoint).

    state["stocks"][symbol] = rec

    try:
        _save("state.json", state)
    except Exception:
        return _err("CONFLICT", "Failed to persist updated stock price.")

    return {
        "symbol": symbol,
        "stock": rec
    }
